#!/bin/bash
# =============================================================================
# Flipper Emulator 13.8 for Linux - installer
#
# NOT affiliated with or endorsed by Flipper Devices or GitHub.
#
# Double-click this file (or start it with: bash "FlipperEmulator 13.8.sh").
# A setup window shows each step. It asks once for your password to install
# the packages the program needs (Mono, QEMU, ...) and its small administrator
# helper, installs Flipper Emulator for your user and puts an icon on the
# desktop. After that, Flipper Emulator is started from that icon or from the
# application menu, exactly like the Windows version.
#
# Options:  --no-start   do not open the program at the end (text mode)
#           --text       show the setup in the terminal instead of a window
#           --update     used by "Check for updates" inside the program
#           --user-setup used by the .deb package at the first start of a user
# =============================================================================
FLIPPER_EMULATOR_INSTALLER=1
FLIPPER_EMULATOR_VERSION="13.8"
HELPER_VERSION="2"
set -Eeuo pipefail

SELF="$(readlink -f "$0")"
MODE=install
START=1
FORCE_TEXT=0
ICON_ALWAYS=0
for a in "$@"; do
  case "$a" in
    --update) MODE=update; START=0 ;;
    --user-setup) MODE=update; START=0; ICON_ALWAYS=1 ;;
    --no-start) START=0 ;;
    --text) FORCE_TEXT=1 ;;
    -h|--help) sed -n '2,20p' "$SELF" | sed 's/^# \{0,1\}//'; exit 0 ;;
  esac
done

if [ -t 1 ]; then C1=$'\033[1;36m'; C2=$'\033[1;33m'; C3=$'\033[1;31m'; C4=$'\033[1;32m'; C0=$'\033[0m'; else C1=; C2=; C3=; C4=; C0=; fi
say()  { printf '%s==>%s %s\n' "$C1" "$C0" "$*"; }
warn() { printf '%s!! %s %s\n' "$C2" "$C0" "$*"; }
ok()   { printf '%s%s%s\n' "$C4" "$*" "$C0"; }
hold() {
  if [ "${FLIP_IN_TERMINAL:-}" = 1 ]; then
    echo
    read -r -p "Press Enter to close this window " _ || true
  fi
}
die()  { printf '%sXX %s %s\n' "$C3" "$C0" "$*" >&2; hold; exit 1; }
has_display() { [ -n "${DISPLAY:-}${WAYLAND_DISPLAY:-}" ]; }

[ "$(id -u)" -ne 0 ] || die "Please run this installer as your normal user (not as root and not with sudo). It asks for your password by itself."

DATA="$HOME/.local/share"
PROG="$DATA/flipper-emulator"
HELPER=/usr/local/lib/flipper-emulator/flipper-root

case "$(uname -m)" in
  x86_64|amd64|aarch64|arm64) ARCH_OK=1 ;;
  *) ARCH_OK=0 ;;
esac

# ---------------------------------------------------------------- unpack
# A folder that allows running programs (the password dialog is one).
TBASE="${XDG_RUNTIME_DIR:-}"
[ -n "$TBASE" ] && [ -d "$TBASE" ] && [ -w "$TBASE" ] || TBASE="${TMPDIR:-/tmp}"
TMPD="$(mktemp -d "$TBASE/flipper-emulator-setup.XXXXXX")"
cleanup() { rm -rf "$TMPD"; }
trap cleanup EXIT
LINE="$(awk '/^__FLIPPER_PAYLOAD_BELOW__$/ { print NR + 1; exit 0 }' "$SELF")"
[ -n "$LINE" ] || die "This file is incomplete. Please download it again."
mkdir -p "$TMPD/payload"
tail -n +"$LINE" "$SELF" | tar -xz -C "$TMPD/payload" || die "This file is damaged. Please download it again."
[ -f "$TMPD/payload/FlipperEmulator.exe" ] || die "This file is damaged. Please download it again."
UI_PY="$TMPD/payload/setup-ui.py"

# ---------------------------------------------------------------- checks
winforms_ok() {
  local f found=0
  for f in /usr/lib/mono/4.5/System.Windows.Forms.dll /usr/lib/mono/gac/System.Windows.Forms/*/System.Windows.Forms.dll \
           /usr/lib64/mono/4.5/System.Windows.Forms.dll /usr/lib64/mono/gac/System.Windows.Forms/*/System.Windows.Forms.dll; do
    [ -f "$f" ] && { found=1; break; }
  done
  [ "$found" = 1 ] || return 1
  for f in /usr/lib/libgdiplus.so* /usr/lib/*/libgdiplus.so* /usr/lib64/libgdiplus.so* /usr/local/lib/libgdiplus.so*; do
    [ -e "$f" ] && return 0
  done
  { ldconfig -p 2>/dev/null || /sbin/ldconfig -p 2>/dev/null || true; } | grep -q libgdiplus
}
find_missing() {
  missing=()
  local c
  for c in mono qemu-system-aarch64 zstd rsync curl git python3 tar xz mformat mkfs.vfat losetup fc-cache xdg-open bwrap; do
    command -v "$c" >/dev/null 2>&1 || missing+=("$c")
  done
  winforms_ok || missing+=("mono-winforms")
  python3 -c 'import ensurepip, venv' >/dev/null 2>&1 || missing+=("python3-venv")
  [ -z "${FLIP_SETUP_TEST_MISSING:-}" ] || missing+=("$FLIP_SETUP_TEST_MISSING")
  return 0
}
# Helper mode: "quick" (its commands run without a password, the default) or
# "password" (sudo asks every time). FLIPPER_HELPER_MODE=password chooses it at
# installation; later: flipper-emulator --helper-mode quick|password
HELPER_MODE="${FLIPPER_HELPER_MODE:-}"
if [ -z "$HELPER_MODE" ]; then
  if [ -e /usr/local/lib/flipper-emulator/ask-password ]; then HELPER_MODE=password; else HELPER_MODE=quick; fi
fi
case "$HELPER_MODE" in quick|password) ;; *) HELPER_MODE=quick ;; esac
helper_ok() {
  [ -x "$HELPER" ] || return 1
  if [ "$HELPER_MODE" = password ]; then
    [ -e /usr/local/lib/flipper-emulator/ask-password ] && grep -q "^HELPER_VERSION=\"$HELPER_VERSION\"" "$HELPER"
  else
    [ ! -e /usr/local/lib/flipper-emulator/ask-password ] && [ "$(sudo -n "$HELPER" version 2>/dev/null || true)" = "$HELPER_VERSION" ]
  fi
}

install_program() {
  # Every step is checked: a failed copy must never remove the installed program.
  mkdir -p "$DATA" || return 1
  NEW="$PROG.new.$$"
  rm -rf "$NEW"
  cp -a "$TMPD/payload" "$NEW" || { rm -rf "$NEW"; return 1; }
  chmod 0755 "$NEW/flipper-emulator" "$NEW/FlipperEmulator.exe" || { rm -rf "$NEW"; return 1; }
  rm -rf "$PROG.old"
  if [ -d "$PROG" ]; then mv "$PROG" "$PROG.old" || { rm -rf "$NEW"; return 1; }; fi
  if ! mv "$NEW" "$PROG"; then
    [ -d "$PROG.old" ] && mv "$PROG.old" "$PROG"
    rm -rf "$NEW"
    return 1
  fi
  rm -rf "$PROG.old"
  return 0
}
install_fonts() {
  # Selawik: open-source, metric-compatible with Segoe UI of the Windows version
  FONTDIR="$DATA/fonts/flipper-emulator"
  mkdir -p "$FONTDIR"
  cp -f "$PROG"/fonts/* "$FONTDIR"/
  command -v fc-cache >/dev/null 2>&1 && fc-cache -f "$FONTDIR" >/dev/null 2>&1 || true
}
install_icons() {
  APPS="$DATA/applications"
  mkdir -p "$APPS"
  DESKTOP_FILE="$APPS/flipper-emulator.desktop"
  cat > "$DESKTOP_FILE" <<EOF
[Desktop Entry]
Type=Application
Version=1.0
Name=Flipper Emulator
GenericName=Flipper One and Flipper Zero emulator
Comment=Unofficial community helper for Flipper One and Flipper Zero emulation
Exec="$PROG/flipper-emulator"
Icon=$PROG/icon.png
Terminal=false
Categories=Development;Emulator;
StartupNotify=true
EOF
  chmod 0755 "$DESKTOP_FILE"
  command -v update-desktop-database >/dev/null 2>&1 && update-desktop-database -q "$APPS" >/dev/null 2>&1 || true
  DESK="$(xdg-user-dir DESKTOP 2>/dev/null || true)"
  [ -n "$DESK" ] && [ "$DESK" != "$HOME" ] || DESK="$HOME/Desktop"
  if [ -d "$DESK" ] || [ "$MODE" = install ] || [ "$ICON_ALWAYS" = 1 ]; then
    mkdir -p "$DESK"
    ICON_FILE="$DESK/flipper-emulator.desktop"
    if [ "$MODE" = install ] || [ "$ICON_ALWAYS" = 1 ] || [ -f "$ICON_FILE" ]; then
      cp -f "$DESKTOP_FILE" "$ICON_FILE"
      chmod 0755 "$ICON_FILE"
      if command -v gio >/dev/null 2>&1; then
        gio set "$ICON_FILE" metadata::trusted true >/dev/null 2>&1 || true
        gio set -t string "$ICON_FILE" metadata::xfce-exe-checksum "$(sha256sum "$ICON_FILE" | cut -d' ' -f1)" >/dev/null 2>&1 || true
      fi
    fi
  fi
}

# ---------------------------------------------------------------- update mode (used by the program itself)
if [ "$MODE" = update ]; then
  find_missing
  if [ ${#missing[@]} -gt 0 ] && [ -x "$HELPER" ]; then
    say "Installing missing system packages: ${missing[*]}"
    sudo -n "$HELPER" deps || warn "Not all packages could be installed."
  fi
  helper_ok || warn "The administrator helper is updated the next time Flipper Emulator needs it (it asks for your password once)."
  command -v mono >/dev/null 2>&1 || die "Mono is missing. Please install the package 'mono-complete' (or 'mono' on Arch)."
  install_program || die "The program files could not be replaced. The installed version is unchanged."
  install_fonts
  install_icons
  echo "OK Flipper Emulator $FLIPPER_EMULATOR_VERSION installed"
  exit 0
fi

# ---------------------------------------------------------------- install mode: choose how to show it
UI=text
if [ "$FORCE_TEXT" = 0 ] && has_display && command -v python3 >/dev/null 2>&1 && \
   FLIP_SETUP_ICON="$TMPD/payload/icon.png" timeout 15 python3 "$UI_PY" --check >/dev/null 2>&1; then
  UI=gui
fi
if [ "$UI" = text ] && [ ! -t 0 ] && [ -z "${FLIP_IN_TERMINAL:-}" ] && has_display; then
  # Double-clicked, but no window toolkit (GTK or Tk for Python) is available: use a terminal.
  export FLIP_IN_TERMINAL=1
  for t in x-terminal-emulator gnome-terminal konsole xfce4-terminal qterminal mate-terminal lxterminal kitty alacritty xterm; do
    command -v "$t" >/dev/null 2>&1 || continue
    case "$t" in
      gnome-terminal) exec gnome-terminal -- bash "$SELF" --text "$@" ;;
      xfce4-terminal|mate-terminal|lxterminal) exec "$t" -e "bash $(printf '%q' "$SELF") --text" ;;
      *) exec "$t" -e bash "$SELF" --text "$@" ;;
    esac
  done
fi

LOGDIR="${XDG_CACHE_HOME:-$HOME/.cache}"
mkdir -p "$LOGDIR"
LOG="$LOGDIR/flipper-emulator-setup.log"
: > "$LOG"
export FLIP_SETUP_TITLE="Flipper Emulator" FLIP_SETUP_VERSION="$FLIPPER_EMULATOR_VERSION" FLIP_SETUP_ICON="$TMPD/payload/icon.png"

# ---------------------------------------------------------------- the steps, reported to the window
UI_GONE=0
ui()     { printf '@@%s\n' "$*" 2>/dev/null || UI_GONE=1; }
detail() { printf '%s\n' "$*" 2>/dev/null || UI_GONE=1; printf '%s\n' "$*" >> "$LOG"; }
fail()   { detail "ERROR: $*"; ui "FAIL $*"; exit 1; }
check_cancel() { [ "$UI_GONE" = 0 ] || { echo "Cancelled by the user." >> "$LOG"; exit 3; }; }

# Runs a command with its output in the log; shows new log lines as details and
# turns the messages of the package managers into progress (from% .. to%).
run_watched() {
  local from="$1" to="$2"; shift 2
  local start rc=0 pid
  start=$(wc -l < "$LOG")
  WATCH_SEEN=$start
  "$@" >> "$LOG" 2>&1 &
  pid=$!
  while kill -0 "$pid" 2>/dev/null; do
    sleep 0.5
    watch_progress "$from" "$to" "$start"
  done
  wait "$pid" || rc=$?
  watch_progress "$from" "$to" "$start"
  return $rc
}
watch_progress() {
  local from="$1" to="$2" start="$3" seen="$WATCH_SEEN" now info
  now=$(wc -l < "$LOG")
  WATCH_SEEN=$now
  if [ "$now" -gt "$seen" ]; then
    tail -n +"$((seen + 1))" "$LOG" | head -n "$((now - seen))" | cut -c1-300 | while IFS= read -r l; do printf '%s\n' "$l" 2>/dev/null || true; done || true
  fi
  info=$(tail -n +"$((start + 1))" "$LOG" | awk '
    /^Hit:|^Ign:/ && !f { lists++ }
    /[0-9]+ upgraded, [0-9]+ newly installed/ { match($0, /[0-9]+ upgraded/); up = substr($0, RSTART, RLENGTH) + 0;
                                                 match($0, /[0-9]+ newly installed/); nw = substr($0, RSTART, RLENGTH) + 0;
                                                 total = up + nw; f = 1; next }
    f && /^Get:/ { g++ } f && /^Unpacking / { u++ } f && /^Setting up / { s++ }
    /^\( *[0-9]+\/[0-9]+\) (installing|upgrading|reinstalling)/ { split($0, a, /[()\/]/); pn = a[2] + 0; pt = a[3] + 0 }
    /^ *(Installing|Upgrading) *: .* [0-9]+\/[0-9]+ *$/ { n = split($NF, a, "/"); pn = a[1] + 0; pt = a[2] + 0 }
    END { printf "%d %d %d %d %d %d %d\n", total, g, u, s, pn, pt, lists }')
  set -- $info
  local total=$1 g=$2 u=$3 s=$4 pn=$5 pt=$6 frac=-1 text=""
  if [ "$total" -gt 0 ]; then
    frac=$(( (45 * (g > total ? total : g) + 20 * (u > total ? total : u) + 35 * (s > total ? total : s)) / total ))
    if [ "$s" -gt 0 ]; then text="Setting up packages ($s of $total)"
    elif [ "$u" -gt 0 ]; then text="Unpacking packages ($u of $total)"
    else text="Downloading packages ($g of $total)"; fi
  elif [ "$pt" -gt 0 ]; then
    frac=$(( 100 * pn / pt )); text="Installing packages ($pn of $pt)"
  elif grep -q 'Reading the package lists\|Reading package lists' <(tail -n +"$((start + 1))" "$LOG"); then
    text="Reading the package lists ..."
  fi
  [ -n "$text" ] && ui "STATUS $text"
  if [ "$frac" -ge 0 ]; then
    ui "PROGRESS $(( from + (to - from) * frac / 100 ))"
  fi
}

setup_main() {
  ui "STEPS Preparing|Administrator rights|Installing system packages|Installing Flipper Emulator"
  ui "LOGFILE $LOG"
  ui "STEP 0 active"
  ui "STATUS Checking this computer ..."
  ui "PROGRESS 2"
  detail "Flipper Emulator $FLIPPER_EMULATOR_VERSION setup, $(date), user $(id -un), $(uname -srm)"
  [ "$ARCH_OK" = 1 ] || detail "Note: this computer is $(uname -m). Flipper Emulator is made for x86_64 and aarch64; some parts may not work."
  find_missing
  local need_helper=0
  helper_ok || need_helper=1
  if [ ${#missing[@]} -gt 0 ]; then detail "Missing on this computer: ${missing[*]}"; else detail "All system packages are already installed."; fi
  [ "$need_helper" = 1 ] && detail "The administrator helper is set up now." || detail "The administrator helper is already set up."
  ui "STEP 0 done"
  check_cancel

  local p_admin=5 p_pkg=8 p_prog=92
  if [ ${#missing[@]} -eq 0 ] && [ "$need_helper" = 0 ]; then p_prog=10; fi

  # -- administrator rights
  if [ ${#missing[@]} -gt 0 ] || [ "$need_helper" = 1 ]; then
    ui "STEP 1 active"
    ui "PROGRESS $p_admin"
    ui "STATUS Waiting for your password ..."
    ui "HINT Your password is needed once. It goes to your system (sudo) and is not stored."
    command -v sudo >/dev/null 2>&1 || fail "sudo is not installed. Please install sudo and add your user to the sudo group (wheel on Arch and Fedora), then start this file again."
    cat > "$TMPD/helper-install.sh" <<'FLIPPER_HELPER_INSTALL'
set -e
U="${SUDO_USER:-}"
if [ -z "$U" ] || [ "$U" = root ]; then echo 'Please start Flipper Emulator from your own user account.' >&2; exit 4; fi
case "$U" in *[!A-Za-z0-9._-]*|-*) echo "This user name cannot be used in a sudo rule: $U" >&2; exit 4;; esac
SRC="$1"
MODE="${2:-quick}"
case "$MODE" in quick|password) ;; *) echo "Unknown helper mode: $MODE" >&2; exit 7;; esac
[ -s "$SRC" ] || { echo "The helper file is missing: $SRC" >&2; exit 5; }
D=/usr/local/lib/flipper-emulator
H="$D/flipper-root"
install -d -m 0755 -o root -g root "$D"
install -m 0755 -o root -g root "$SRC" "$H.new"
mv -f "$H.new" "$H"
if [ "$MODE" = password ]; then TAG=""; else TAG="NOPASSWD: "; fi
SAFE="$(printf '%s' "$U" | tr -c 'A-Za-z0-9_-' '_')"
RULE="/etc/sudoers.d/flipper-emulator-$SAFE"
TMP="$(mktemp)"
{
  echo "# Flipper Emulator administrator helper: only these commands, nothing else."
  echo "# Mode: $MODE (change it with: flipper-emulator --helper-mode quick|password)"
  printf '%s ALL=(root) %s%s version, %s deps, %s install-preview, %s extract-boot, %s guest-net, %s guest-shelf, %s guest-files Export, %s guest-files Import, %s guest-color, %s guest-color [a-z0-9]*, %s remove-self\n' "$U" "$TAG" "$H" "$H" "$H" "$H" "$H" "$H" "$H" "$H" "$H" "$H" "$H"
} > "$TMP"
if ! visudo -cf "$TMP" >/dev/null; then rm -f "$TMP"; echo 'The sudo rule could not be checked.' >&2; exit 6; fi
install -m 0440 -o root -g root "$TMP" "$RULE.new"
rm -f "$TMP"
mv -f "$RULE.new" "$RULE"
if ! visudo -c >/dev/null 2>&1; then rm -f "$RULE"; echo 'The sudo configuration did not accept the rule; it was removed again.' >&2; exit 6; fi
if [ "$MODE" = password ]; then install -m 0644 -o root -g root /dev/null "$D/ask-password"; else rm -f "$D/ask-password"; fi
echo "OK administrator helper installed ($MODE mode)"

FLIPPER_HELPER_INSTALL
    local rc=0
    if [ "$UI" = gui ]; then
      printf '#!/bin/sh\nexec python3 %s --askpass "$@"\n' "$(printf '%q' "$UI_PY")" > "$TMPD/askpass"
      chmod 0700 "$TMPD/askpass"
      echo 0 > "$TMPD/askpass.count"
      SUDO_ASKPASS="$TMPD/askpass" FLIP_ASKPASS_COUNT="$TMPD/askpass.count" \
        sudo -A -p "Password: " bash "$TMPD/helper-install.sh" "$TMPD/payload/flipper-root" "$HELPER_MODE" >> "$LOG" 2>&1 || rc=$?
    else
      ui "STATUS Please type your password in this terminal (it is not shown while you type):"
      sudo -p "    Password for %u: " bash "$TMPD/helper-install.sh" "$TMPD/payload/flipper-root" "$HELPER_MODE" >> "$LOG" 2>&1 || rc=$?
    fi
    if [ "$rc" -ne 0 ]; then
      if grep -q 'not in the sudoers\|not allowed to run sudo\|may not run sudo' "$LOG"; then
        fail "Your user account is not allowed to use administrator rights (sudo). Please ask the owner of this computer to add you to the sudo group (wheel on Arch and Fedora)."
      elif grep -q 'incorrect password attempt' "$LOG"; then
        fail "The password was not accepted. Please start this file again and enter the password you use to log in."
      elif grep -qi 'no password was provided\|a password is required' "$LOG"; then
        fail "No password was entered, so nothing was changed. Start this file again when you are ready."
      fi
      fail "The administrator helper could not be set up (code $rc). See the details below."
    fi
    detail "Administrator helper installed."
    ui "HINT "
    ui "STEP 1 done"
  else
    ui "STEP 1 skip"
  fi
  check_cancel

  # -- system packages
  if [ ${#missing[@]} -gt 0 ]; then
    ui "STEP 2 active"
    ui "PROGRESS $p_pkg"
    ui "STATUS Starting the package manager ..."
    ui "HINT This usually takes 5 to 15 minutes, depending on your internet connection. You can keep using your computer."
    local rc=0
    run_watched "$p_pkg" "$((p_prog - 1))" sudo -n "$HELPER" deps || rc=$?
    ui "HINT "
    if [ "$rc" -ne 0 ]; then
      if grep -q 'Could not get lock\|is held by process\|Unable to acquire the dpkg' "$LOG"; then
        fail "Another program is installing updates right now (the package manager is busy). Please wait until it has finished, then start this file again."
      fi
      detail "The package manager reported a problem (code $rc). Checking what is installed ..."
    fi
    find_missing
    command -v mono >/dev/null 2>&1 || fail "Mono could not be installed. Please install the package 'mono-complete' (or 'mono' on Arch) and start this file again."
    winforms_ok || fail "Mono Windows Forms could not be installed. Please install 'libmono-system-windows-forms4.0-cil' and 'libgdiplus' (Debian, Ubuntu, Kali) or 'mono' and 'libgdiplus' (Arch) and start this file again."
    [ ${#missing[@]} -eq 0 ] || detail "Still missing (Flipper Emulator installs these later when needed, or some features are unavailable): ${missing[*]}"
    ui "STEP 2 done"
  else
    ui "STEP 2 skip"
  fi
  check_cancel

  # -- the program
  ui "STEP 3 active"
  ui "PROGRESS $p_prog"
  ui "STATUS Copying Flipper Emulator to your user folder ..."
  install_program >> "$LOG" 2>&1 || fail "The program files could not be copied to $PROG (is the disk full?)."
  ui "PROGRESS $(( p_prog + (100 - p_prog) * 4 / 10 ))"
  ui "STATUS Installing the fonts ..."
  install_fonts >> "$LOG" 2>&1 || detail "The fonts could not be installed; the window uses a default font."
  ui "PROGRESS $(( p_prog + (100 - p_prog) * 7 / 10 ))"
  ui "STATUS Adding the desktop icon and the menu entry ..."
  install_icons >> "$LOG" 2>&1 || detail "The desktop icon could not be created; use the application menu."
  detail "Installed to $PROG"
  ui "STEP 3 done"
  ui "DONE $PROG/flipper-emulator"
  return 0
}

if [ "$UI" = gui ]; then
  trap '' PIPE
  [ -t 1 ] && echo "The Flipper Emulator setup window is open. Follow the steps there."
  set +e
  ( set -eE; trap 'ui "FAIL Unexpected error in the setup (line $LINENO). Please report it with the details below."' ERR; setup_main ) | python3 "$UI_PY" --gui
  st=${PIPESTATUS[0]}
  set -e
  [ -t 1 ] && { [ "$st" = 0 ] && echo "Flipper Emulator $FLIPPER_EMULATOR_VERSION is installed." || echo "The setup did not finish (log: $LOG)."; }
  exit "$st"
fi

# text mode (terminal)
set +e
if command -v python3 >/dev/null 2>&1; then
  ( set -eE; trap 'ui "FAIL Unexpected error in the setup (line $LINENO)."' ERR; setup_main ) | python3 "$UI_PY" --text
  rc=${PIPESTATUS[0]}
else
  ( set -eE; setup_main ) | while IFS= read -r l; do
    case "$l" in
      "@@STATUS "*) echo "    ${l#@@STATUS }" ;;
      "@@FAIL "*)   echo "XX  ${l#@@FAIL }" ;;
      "@@DONE "*)   echo "OK  Flipper Emulator $FLIPPER_EMULATOR_VERSION is installed." ;;
    esac
  done
  rc=${PIPESTATUS[0]}
fi
set -e
if [ "$rc" = 0 ] && [ "$START" = 1 ] && has_display; then
  echo "Opening Flipper Emulator ..."
  (cd "$HOME" && setsid "$PROG/flipper-emulator" >/dev/null 2>&1 < /dev/null &)
  sleep 1
fi
hold
exit "$rc"
__FLIPPER_PAYLOAD_BELOW__
